// Updog.link — the whole application.
//
// Two hostnames, one Worker:
//   <site>/            the landing page with the create form  (whats.updog.link)
//   <apex>/            301 to <site>                          (updog.link)
//   <apex>/:slug       302 to the destination, or the 404 page
//   POST /api/links    create a link  {slug, destination, token}  (both hosts)
//
// Bindings (see terraform/worker.tf and wrangler.jsonc):
//   LINKS             R2 bucket; one JSON object per link, keyed by slug
//   TURNSTILE_SECRET  server-side key for verifying the bot check
//   TURNSTILE_SITEKEY public key rendered into the form
//   GITHUB_REPO       "owner/name", linked from the page
//   DONATE_URL        optional; donation line is shown only when set
//   APEX_HOST         hostname that serves shortlinks. Empty in local dev.
//   SITE_HOST         hostname that serves the landing page. Empty in local dev.

// Slugs become R2 object keys and appear in URLs, so the allowed set is kept
// deliberately narrow: ASCII letters, digits, underscore and hyphen, starting
// with an alphanumeric, 1-64 characters. That excludes "/", "\\", ".", "%" and
// whitespace, so path traversal and encoding tricks can't be expressed at all,
// and excludes "<", ">", quotes, so a slug can never break out into markup.
const SLUG_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;

// "api" is a real route. The rest are reserved to avoid confusion rather than
// for safety. Anything containing a dot is already unmatchable by SLUG_RE.
const RESERVED = new Set(["api", "admin", "favicon", "robots", "static", "assets"]);

const MAX_DESTINATION_LENGTH = 2048;

// Word pairs for auto-named links, e.g. "plucky-corgi". 48 x 48 is 2304 base
// combinations, and a numeric suffix is added if the first tries collide.
const ADJECTIVES = [
  "bold", "bouncy", "brave", "cheerful", "clever", "curious", "dapper", "eager",
  "fancy", "fuzzy", "gentle", "glad", "golden", "grumpy", "happy", "hungry",
  "jolly", "lanky", "lively", "loyal", "lucky", "merry", "mighty", "nimble",
  "noble", "perky", "plucky", "proud", "quiet", "rapid", "rowdy", "scruffy",
  "shaggy", "silly", "sleepy", "snappy", "snug", "speedy", "spotted", "sturdy",
  "sunny", "swift", "tidy", "trusty", "wiggly", "witty", "zany", "zippy",
];
const NOUNS = [
  "bark", "beagle", "biscuit", "bone", "boxer", "buddy", "chew", "collar",
  "collie", "comet", "corgi", "dachshund", "dash", "echo", "ember", "fetch",
  "finch", "hazel", "howl", "husky", "juniper", "kennel", "kibble", "leash",
  "maple", "mutt", "muzzle", "nimbus", "paw", "pebble", "poodle", "pounce",
  "pug", "puppy", "ranger", "retriever", "romp", "scout", "setter", "snout",
  "spaniel", "tail", "terrier", "treat", "wag", "whippet", "willow", "zoomies",
];

function pick(list) {
  return list[Math.floor(Math.random() * list.length)];
}

// Attempts past the first few add digits, so a busy shortener still finds a
// free name quickly instead of retrying the same small space.
function randomSlug(attempt = 0) {
  const base = `${pick(ADJECTIVES)}-${pick(NOUNS)}`;
  return attempt < 2 ? base : `${base}-${Math.floor(Math.random() * 900) + 100}`;
}

// Example links. The landing page shows a different one as its placeholder on
// every render, and `node scripts/seed.mjs` creates them for real so a fresh
// deploy isn't a completely empty shortener. Single source of truth for both.
export const SAMPLES = [
  ["github", "https://github.com"],
  ["gmail", "https://gmail.com"],
  ["wikipedia", "https://wikipedia.org"],
  ["hackernews", "https://news.ycombinator.com"],
  ["maps", "https://maps.google.com"],
  ["weather", "https://weather.gov"],
  ["cloudflare", "https://cloudflare.com"],
];

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const { pathname } = url;
    const apex = env.APEX_HOST;
    const site = env.SITE_HOST;
    const routed = Boolean(apex && site); // false in local dev, where host is localhost
    const singleHost = routed && site === apex; // landing page and shortlinks share one host
    const onSite = routed && url.hostname === site;

    // Anything that isn't one of the configured hostnames (the workers.dev
    // preview, say) belongs on the apex.
    if (routed && url.hostname !== apex && !onSite) {
      return redirect(`https://${apex}${pathname}${url.search}`, 301);
    }

    if (pathname === API_ROOT || pathname.startsWith(API_ROOT + "/")) {
      return apiLinks(request, env, url);
    }
    // Any other /api path is an API mistake, so answer in JSON rather than
    // falling through to the HTML 404.
    if (pathname === "/api" || pathname.startsWith("/api/")) {
      return json({ error: `Unknown endpoint. The only resource is ${API_ROOT}.` }, 404);
    }
    if (request.method !== "GET" && request.method !== "HEAD") {
      return json({ error: "Method not allowed." }, 405);
    }
    if (pathname === "/favicon.ico") return new Response(null, { status: 204 });
    if (pathname === "/robots.txt") return new Response("User-agent: *\nDisallow: /api/\n");

    if (pathname === "/") {
      if (onSite || !routed) return html(landingPage(env));
      return redirect(`https://${site}/`, 301);
    }
    // When the landing page has its own subdomain, shortlinks live on the
    // apex. Reaching one via the site host is harmless; send it next door
    // rather than 404ing. In single-host mode there's nowhere else to send it.
    if (onSite && !singleHost) return redirect(`https://${apex}${pathname}${url.search}`, 301);

    const slug = pathname.slice(1);
    if (SLUG_RE.test(slug) && !RESERVED.has(slug)) {
      const object = await env.LINKS.get(slug);
      if (object) {
        const { destination } = await object.json();
        return redirect(destination, 302, { "Cache-Control": "no-store" });
      }
    }
    return html(notFoundPage(env), 404);
  },
};

async function createLink(request, env, url) {
  // CSRF guard. A cross-origin HTML form can only send urlencoded, form-data or
  // text/plain; requiring JSON forces a preflight, which this Worker never
  // answers. There is no session or cookie to abuse either, so this is defence
  // in depth rather than the only thing standing in the way.
  const contentType = request.headers.get("Content-Type") || "";
  if (!contentType.toLowerCase().startsWith("application/json")) {
    return json({ error: "Expected Content-Type: application/json." }, 415);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Body must be JSON." }, 400);
  }
  const slug = String(body.slug ?? "").trim();
  const token = String(body.token ?? "");
  const linkHost = env.APEX_HOST || url.host;

  // An omitted or empty slug means "you pick one for me".
  const autoName = slug === "";
  if (!autoName) {
    if (!SLUG_RE.test(slug)) {
      return json({ error: "Slug must be 1–64 letters, digits, dashes or underscores." }, 400);
    }
    if (RESERVED.has(slug)) return json({ error: "That slug is reserved." }, 400);
  }

  const ownHosts = [env.APEX_HOST, env.SITE_HOST, url.hostname].filter(Boolean);
  const destination = parseDestination(String(body.destination ?? "").trim(), ownHosts);
  if (!destination) {
    return json({ error: "Destination must be an http(s) URL that doesn't point back here." }, 400);
  }

  const human = await verifyTurnstile(token, env.TURNSTILE_SECRET, request.headers.get("CF-Connecting-IP"));
  if (!human) return json({ error: "Bot check failed. Reload the page and try again." }, 403);

  const scheme = url.protocol === "http:" && !env.APEX_HOST ? "http" : "https";

  // A name the caller chose gets one attempt — if it's taken, that's a 409 and
  // they pick another. A name we chose gets several, since a collision is our
  // problem to solve, not theirs.
  const attempts = autoName ? 6 : 1;
  for (let attempt = 0; attempt < attempts; attempt++) {
    const name = autoName ? randomSlug(attempt) : slug;
    if (autoName && RESERVED.has(name)) continue;

    const record = JSON.stringify({ slug: name, destination, created_at: new Date().toISOString() });
    const stored = await env.LINKS.put(name, record, {
      httpMetadata: { contentType: "application/json" },
      onlyIf: new Headers({ "If-None-Match": "*" }), // first come, first served
    });

    if (stored !== null) {
      return json({ slug: name, url: `${scheme}://${linkHost}/${name}`, destination }, 201);
    }
    if (!autoName) return json({ error: `${linkHost}/${name} is already taken.` }, 409);
  }

  return json({ error: "Couldn't find a free name. Try again." }, 503);
}

// A hostname with a trailing dot ("updog.link.") is the same DNS name as one
// without, and resolves to the same server — so it has to be normalised before
// comparing, or it becomes a way to point a link back at this service.
function normalizeHost(host) {
  return host.replace(/\.+$/, "").toLowerCase();
}

function parseDestination(raw, ownHosts) {
  // Rejecting whitespace also rejects CR and LF, so a destination can't inject
  // extra response headers via the Location value.
  if (!raw || raw.length > MAX_DESTINATION_LENGTH || /\s/.test(raw)) return null;
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    return null;
  }
  // Only http(s): blocks javascript:, data:, file: and friends.
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;

  // Never point at ourselves, on any hostname this service answers to, at any
  // depth. Stops redirect loops at the source.
  const host = normalizeHost(parsed.hostname);
  const mine = ownHosts.map(normalizeHost);
  if (mine.some((own) => host === own || host.endsWith("." + own))) return null;

  return parsed.href;
}

async function verifyTurnstile(token, secret, ip) {
  if (!token) return false;
  const form = new FormData();
  form.append("secret", secret);
  form.append("response", token);
  if (ip) form.append("remoteip", ip);
  const res = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
    method: "POST",
    body: form,
  });
  const data = await res.json();
  return data.success === true;
}

// --- api ---------------------------------------------------------------------

// /api/links          GET describes the resource, POST creates a link
// /api/links/<slug>   GET reads one link; PUT and DELETE are deliberate stubs
const API_ROOT = "/api/links";

async function apiLinks(request, env, url) {
  const tail = url.pathname.slice(API_ROOT.length);
  const slug = tail.replace(/^\//, "");

  if (!slug) {
    switch (request.method) {
      case "GET":
      case "HEAD":
        return json({
          resource: API_ROOT,
          methods: {
            "POST /api/links": "create a link from {destination, token} and an optional slug; omit slug and one is generated",
            "GET /api/links/<slug>": "look up a single link",
            "PUT /api/links/<slug>": "not implemented; links are immutable",
            "DELETE /api/links/<slug>": "not implemented; removal is an operator action",
          },
          // Deliberately not listable. Every link is public to anyone who knows
          // its name, but handing out the whole set is a different thing.
          listing: "not available",
        });
      case "POST":
        return createLink(request, env, url);
      default:
        return methodNotAllowed(["GET", "POST"]);
    }
  }

  switch (request.method) {
    case "GET":
    case "HEAD":
      return readLink(slug, env, url);
    // Editing would break the promise that a link, once made, keeps pointing
    // where it pointed. Deletion is an operator action against the bucket, on
    // purpose: anyone could otherwise remove a link they didn't create.
    case "PUT":
    case "PATCH":
      return json({ error: "Not implemented. Links can't be edited once created." }, 501);
    case "DELETE":
      return json({ error: "Not implemented. To report a link, open an issue." }, 501);
    default:
      return methodNotAllowed(["GET"]);
  }
}

async function readLink(slug, env, url) {
  // Validate before touching R2, exactly as the redirect path does, so a
  // crafted path can never reach storage as a key.
  if (!SLUG_RE.test(slug) || RESERVED.has(slug)) {
    return json({ error: "Not a valid shortlink name." }, 400);
  }
  const object = await env.LINKS.get(slug);
  if (!object) return json({ error: "No such shortlink." }, 404);

  const record = await object.json();
  const linkHost = env.APEX_HOST || url.host;
  const scheme = url.protocol === "http:" && !env.APEX_HOST ? "http" : "https";
  return json({
    slug,
    destination: record.destination,
    created_at: record.created_at ?? null,
    url: `${scheme}://${linkHost}/${slug}`,
  });
}

function methodNotAllowed(allowed) {
  return new Response(JSON.stringify({ error: `Method not allowed. Try ${allowed.join(" or ")}.` }), {
    status: 405,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      Allow: allowed.join(", "),
    },
  });
}

// --- responses ---------------------------------------------------------------

function redirect(location, status, extra = {}) {
  return new Response(null, { status, headers: { Location: location, ...extra } });
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8" },
  });
}

function html(markup, status = 200) {
  return new Response(markup, {
    status,
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

