function layout(title, env, body) {
  const repoUrl = `https://github.com/${esc(env.GITHUB_REPO)}`;
  const donateLink = env.DONATE_URL ? `<a href="${esc(env.DONATE_URL)}">Donate</a>` : "";
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<link rel="icon" href="${FAVICON}">
<style>${FONTS}</style>
<style>${STYLE}</style>
</head>
<body>
<div class="page">
  <header>
    <div class="wordmark">${esc(env.APEX_HOST || "UPDOG.LINK").toUpperCase()}</div>
    <nav><a href="${repoUrl}">GitHub</a>${donateLink}</nav>
  </header>
  <main>
${body}
  </main>
  <footer>But no, really — what is "Updog"?
    <a href="https://knowyourmeme.com/memes/updog">Nothin' much. What's up with you?</a></footer>
</div>
</body>
</html>`;
}

function landingPage(env) {
  const repoUrl = `https://github.com/${esc(env.GITHUB_REPO)}`;
  const linkHost = esc(env.APEX_HOST || "updog.link");
  // A different example on every render, so the form suggests something real.
  const [sampleSlug, sampleUrl] = SAMPLES[Math.floor(Math.random() * SAMPLES.length)];
  const donate = env.DONATE_URL
    ? ` Donations cover hosting fees; proceeds are forwarded to the
       <a href="https://girlswhocode.com/">Girls Who Code Foundation</a>.`
    : "";

  return layout(
    "What's Updog?",
    env,
    `
    <div class="doggo">🐶</div>
    <h1>What's <em>Updog?</em></h1>
    <p class="tagline">An ad-free, open-source URL shortener that anyone can deploy and run.
      No ads, no tracking.</p>

    <form id="create">
      <div class="field">
        <span class="prefix">${linkHost}/</span>
        <label for="slug" hidden>Shortlink name</label>
        <input type="text" id="slug" name="slug" placeholder="${esc(sampleSlug)}"
               maxlength="64" pattern="[A-Za-z0-9_-]+" autocapitalize="off" spellcheck="false">
        <button type="button" id="roll" class="roll" title="Pick a name for me">Generate</button>
      </div>
      <div class="row">
        <div class="field">
          <label for="destination" hidden>Destination URL</label>
          <input type="url" id="destination" name="destination" placeholder="${esc(sampleUrl)}" required>
        </div>
        <button type="submit">Go! 🐕</button>
      </div>
      <div class="cf-turnstile" data-sitekey="${esc(env.TURNSTILE_SITEKEY)}"></div>
      <p id="result" aria-live="polite"></p>
    </form>
    <p class="fine">Leave the name blank and one gets picked for you. Links can't be edited once created.
      Report abusive links <a href="${repoUrl}/issues">on GitHub</a>.</p>

    <div class="sections">
      <div>
        <h2>Why it exists</h2>
        <p>A free shortlink service with a
          <a href="https://www.urbandictionary.com/define.php?term=Sick"><em>sick</em></a> name — and no
          interest in tracking you or anyone else.${donate}</p>
      </div>
      <div>
        <h2>There's an API</h2>
        <p>This page is just a client of it. Look a link up, or create one by posting to the same resource.
          <a href="${repoUrl}/blob/master/SELF_HOSTING.md#the-api">The docs</a> cover the rest.</p>
        <pre><code>curl ${linkHost}/api/links/&lt;slug&gt;</code></pre>
      </div>
      <div>
        <h2>Run your own</h2>
        <p>Deployment takes about ten minutes, start to finish. It runs on Cloudflare's free tier, so serving
          a few million redirects a month costs nothing. Clone
          <a href="${repoUrl}">the repository</a> to give it a try.</p>
      </div>
    </div>

<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>
<script>
  const form = document.getElementById("create");
  const result = document.getElementById("result");
  const slug = document.getElementById("slug");

  // Same lists the Worker uses, so a rolled name looks like an auto-named one.
  // Leaving the field empty asks the server to pick instead, which it retries
  // on collision; rolling here is just so you can see and re-roll the name.
  const ADJECTIVES = ${JSON.stringify(ADJECTIVES)};
  const NOUNS = ${JSON.stringify(NOUNS)};
  const pick = (list) => list[Math.floor(Math.random() * list.length)];
  const roll = () => pick(ADJECTIVES) + "-" + pick(NOUNS);

  // Check the name is free before offering it, so you don't get told a name
  // you never chose was taken. A Turnstile token is single use, so retrying
  // after a rejected submit would need a fresh one — far simpler to look first.
  async function isTaken(name) {
    try {
      const res = await fetch("/api/links/" + encodeURIComponent(name));
      return res.status === 200;
    } catch {
      return false; // offline or blocked: offer it anyway, the server decides
    }
  }

  const rollButton = document.getElementById("roll");
  rollButton.addEventListener("click", async () => {
    rollButton.disabled = true;
    try {
      let name = roll();
      for (let i = 0; i < 3 && (await isTaken(name)); i++) name = roll();
      slug.value = name;
      slug.focus();
    } finally {
      rollButton.disabled = false;
    }
  });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    result.textContent = "Working…";
    let res, body;
    try {
      res = await fetch("/api/links", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          slug: data.get("slug"),
          destination: data.get("destination"),
          token: data.get("cf-turnstile-response"),
        }),
      });
      body = await res.json();
    } catch {
      body = { error: "Something went wrong. Try again." };
    }
    result.textContent = "";
    if (res && res.ok) {
      const a = document.createElement("a");
      a.href = body.url;
      a.textContent = body.url;
      result.append("Done: ", a);
    } else {
      result.textContent = body.error || "Something went wrong.";
      // Someone took it in the meantime. Offer a fresh name so the next
      // attempt isn't the same collision.
      if (res && res.status === 409) rollButton.click();
    }
    if (window.turnstile) turnstile.reset();
  });
</script>
`
  );
}

function notFoundPage(env) {
  const site = env.SITE_HOST ? `https://${esc(env.SITE_HOST)}/` : "/";
  return layout(
    "404 · What's Updog?",
    env,
    `
    <div class="doggo">🐕</div>
    <h1>Nothin' <em>much.</em></h1>
    <p class="tagline">That shortlink doesn't exist.</p>
    <p><a href="${site}">Make one instead</a></p>
`
  );
}

// Latin subsets of Bitter, Gabarito and JetBrains Mono, inlined so the page
// pulls no third-party requests and nothing can track visitors. Three are
// variable fonts, hence the weight ranges — one blob per file, not per weight.
// Only the landing and 404 pages ever load these; redirects have no body.
// Diffing this constant is not meaningful; regenerate it rather than edit it.
const FONTS = `@font-face{font-family:'Bitter';font-weight: 400 600; font-style: normal; font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Bitter';font-weight: 400;     font-style: italic; font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Gabarito';font-weight: 500 900; font-style: normal; font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'JetBrains Mono';font-weight: 400 600; font-style: normal; font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}`;
